import { documentFromHistory, type CanvasHistoryRecord } from './canvasHistory';
import { validateDiagram, diagramSource, type Diagram, type DiagramSourceBinding } from './diagram';
import { RevisionedDiagramService } from './diagramService';
import {
  composeScene,
  flattenGrid,
  measureContent,
  resolveScene,
  type LineGridScene
} from "./lineGrid";
import type { ProjectRepresentationEvidenceRecord, ProjectRepresentationMappingRecord, ProjectRepresentationRevisionRecord } from "../representations/projectCatalog";

export type ProjectDiagramContent = { kind: "canvas-history"; history: CanvasHistoryRecord };
export interface SaveProjectDiagramInput {
  repositoryId?: string;
  history: CanvasHistoryRecord;
  projectId?: string;
  representationId?: string;
  expectedRevisionId?: string;
  sourceRevisionId?: string;
  name: string;
  scene: LineGridScene;
  edges?: import('./diagramConnection').DiagramConnection[];
}

export function singleDiagramScene(ascii: string, source?: DiagramSourceBinding): LineGridScene {
  return { contents: {
    overview: new RevisionedDiagramService().create({ id: "overview", revision: 0, ascii, source }).diagram,
    "overview-summary": new RevisionedDiagramService().create({ id: "overview-summary", revision: 0, ascii: "[Diagram]" }).diagram
  }, root: { id: "root", kind: "container", position: { column: 0, row: 0 }, collapsed: false,
    layout: { collisionPolicy: "push-right", gap: 3 }, children: [
      { id: "overview", kind: "diagram", position: { column: 0, row: 0 }, collapsed: false,
        contentId: "overview", collapsedContentId: "overview-summary" }
    ] } };
}

export function sceneFromRevision(revision: ProjectRepresentationRevisionRecord): LineGridScene {
  return documentFromHistory(historyFromRevision(revision)).scene;
}

/** Validate composition without generating an ASCII/source-evidence export. */
export function validateCanvasScene(scene: LineGridScene, validatedDiagrams?: ReadonlySet<Diagram>) {
  if (!scene || !scene.contents || !scene.root || Object.keys(scene.contents).length > 500) throw new Error("Invalid Mapping canvas");
  let boxes = 0;
  const walk = (box: LineGridScene["root"], depth = 0) => {
    if (!box || depth > 32 || ++boxes > 1000 || typeof box.id !== "string" || !box.id) throw new Error("Invalid canvas hierarchy");
    if (box.kind !== "diagram" && box.kind !== "container") throw new Error("Invalid canvas box kind");
    if (typeof box.collapsed !== "boolean") throw new Error("Invalid collapsed state");
    if (box.collapsedContentId && !scene.contents[box.collapsedContentId]) throw new Error("Unknown collapsed canvas content");
    if (box.kind === "container") {
      if (!Array.isArray(box.children) || !box.layout || box.layout.collisionPolicy !== "push-right") throw new Error("Invalid canvas container");
      box.children.forEach((child) => walk(child, depth + 1));
    }
  };
  walk(scene.root);
  // Also resolve the expanded hierarchy so hidden children cannot bypass validation.
  const expand = (box: LineGridScene["root"]): LineGridScene["root"] => box.kind === "container"
    ? { ...box, collapsed: false, children: box.children.map(expand) } : { ...box, collapsed: false };
  resolveScene({ ...scene, root: expand(scene.root) });
  for (const [id, diagram] of Object.entries(scene.contents)) {
    if (diagram.id !== id || !Number.isInteger(diagram.revision) || diagram.revision < 0 || !diagram.content) throw new Error("Invalid canvas diagram");
    if (!validatedDiagrams?.has(diagram)) validateDiagram(diagram);
    measureContent(diagram.content.ascii);
  }
}

/** Validate all content (including collapsed content), then derive the visible export. */
export function projectCanvasSnapshot(scene: LineGridScene) {
  validateCanvasScene(scene);
  const evidence: Record<string, ProjectRepresentationEvidenceRecord> = {};
  const evidenceIds = new Map<string, string>();
  for (const [id, diagram] of Object.entries(scene.contents)) {
    for (const [key, entry] of Object.entries(diagram.sourceContext.evidence)) {
      // Export IDs are scoped by source and diagram. Local evidence IDs remain untouched.
      const exported = exportedEvidenceId(scene, id, key);
      evidenceIds.set(`${id}:${key}`, exported);
      evidence[exported] = { ...structuredClone(entry), sourceRanges: entry.sourceRanges.map(range => ({ ...range, originalLines: [...range.originalLines] })), id: exported, sourceId: diagram.sourceContext.binding?.sourceId };
    }
  }
  const ascii = composeScene(scene);
  const mappings: ProjectRepresentationMappingRecord[] = [];
  for (const node of flattenGrid(resolveScene(scene))) {
    if (!node.contentId) continue;
    const diagram = scene.contents[node.contentId];
    for (const {mapping, range} of diagramSource(diagram).entries()) {
      mappings.push({ id: `${node.box.id}:${mapping.id}`, evidenceId: evidenceIds.get(`${diagram.id}:${mapping.entityId}`)!,
        sourceRangeId: range.id, line: node.bounds.row + mapping.line,
        startColumn: node.bounds.column + mapping.startColumn, endColumn: node.bounds.column + mapping.endColumn });
    }
  }
  return { ascii, mappings, evidence };
}

/** Catalog export addresses; diagram-local IDs remain stable inside source contexts. */
export function exportedEvidenceId(scene: LineGridScene, diagramId: string, evidenceId: string): string {
  const owners = Object.values(scene.contents).filter(d => d.sourceContext.evidence[evidenceId]);
  const signatures = new Set(owners.map(d => JSON.stringify([d.sourceContext.binding?.sourceId, d.sourceContext.evidence[evidenceId]])));
  return signatures.size > 1 ? `${diagramId}:${evidenceId}` : evidenceId;
}

export function edgesFromRevision(revision: ProjectRepresentationRevisionRecord) {
  return documentFromHistory(historyFromRevision(revision)).edges;
}
export function historyFromRevision(revision: ProjectRepresentationRevisionRecord): CanvasHistoryRecord {
  if (revision.content?.kind !== 'canvas-history') throw new Error('Unsupported legacy diagram content: canvas history is required');
  return structuredClone(revision.content.history);
}
export function documentFromRevision(revision: ProjectRepresentationRevisionRecord) {
  return documentFromHistory(historyFromRevision(revision));
}

sources.domain/core/diffs/gitDiffHunk.ts:
import { z } from 'zod';
import { sha256 } from '../sha256';

const sha = z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/);
export const gitDiffHunkSchema = z.object({
  id: z.string().regex(/^hunk-[a-f0-9]{64}$/), repositoryId: z.string().min(1), commit: sha, parent: sha.nullable(),
  path: z.string().min(1), status: z.enum(['A', 'M', 'D', 'T']), kind: z.enum(['text', 'binary', 'metadata']),
  oldStart: z.number().int().nonnegative(), oldLines: z.number().int().nonnegative(),
  newStart: z.number().int().nonnegative(), newLines: z.number().int().nonnegative(), patch: z.string().max(2_000_000)
}).strict();
export type GitDiffHunk = z.infer<typeof gitDiffHunkSchema>;
export function identifyHunk(input: Omit<GitDiffHunk, 'id'>): GitDiffHunk {
  return { id: `hunk-${sha256(JSON.stringify(input))}`, ...input };
}
/** Preserve Git's exact hunk text, including no-newline markers and CR characters. */
export function parseGitFileDiff(input: Pick<GitDiffHunk, 'repositoryId' | 'commit' | 'parent' | 'path' | 'status'>, patch: string): GitDiffHunk[] {
  const starts = [...patch.matchAll(/^@@ -(\d+)(?:,(\d+))? \+(\d+)(?:,(\d+))? @@[^\n]*\n/gm)];
  if (!starts.length) return [identifyHunk({ ...input, kind: /^Binary files /m.test(patch) ? 'binary' : 'metadata',
    oldStart: 0, oldLines: 0, newStart: 0, newLines: 0, patch })];
  return starts.map((match, index) => identifyHunk({ ...input, kind: 'text',
    oldStart: Number(match[1]), oldLines: Number(match[2] ?? 1), newStart: Number(match[3]), newLines: Number(match[4] ?? 1),
    patch: patch.slice(match.index, starts[index + 1]?.index ?? patch.length).split(/^diff --git /m)[0] }));
}

sources.domain/core/records/domain.ts:
export const SCHEMA_VERSION = 1 as const;

export type CodeEntityCategory = "state" | "interface-data-struct" | "operation";
export type SourceCompactionLevel = "low" | "medium" | "high";
export type DiagramViewKind = "diagram" | "call-graph" | "dir-view";
export const DIAGRAM_MODELS = [
  { id: "gpt-5.6-terra", label: "GPT-5.6 Terra" },
  { id: "gpt-5.6-sol", label: "GPT-5.6 Sol" }
] as const;
export type DiagramModelId = typeof DIAGRAM_MODELS[number]["id"];
export const DEFAULT_DIAGRAM_MODEL_ID: DiagramModelId = "gpt-5.6-sol";


/** Stable provenance for a record, independent from where an imported copy is stored. */
export interface ArtifactOrigin {
  projectId: string;
  diagramSetId: string;
}

export interface CodeEntityOrigin extends ArtifactOrigin {
  codeEntitiesSetId: string;
}

export type CompactedSourceSection =
  | {
      kind: "source";
      startLine: number;
      endLine: number;
    }
  | {
      kind: "collapsed-comment";
      startLine: number;
      endLine: number;
      comment: string;
      /** One-based graph-body line to source-block mappings. Optional for legacy records. */
      nodes?: CompactedSourceNode[];
    };

export interface CompactedSourceNode {
  graphLine: number;
  startLine: number;
  endLine: number;
}

export interface CompactedSource {
  level: SourceCompactionLevel;
  sections: CompactedSourceSection[];
}

export interface SourceRange {
  /** Globally unique on new records. Optional only while reading legacy records. */
  id?: string;
  path: string;
  startLine: number;
  endLine: number;
  symbol?: string;
  /** Immutable source snapshot captured when this CodeEntity was collected. */
  originalLines?: string[];
  /** Optional presentation map; absent ranges render as their complete source. */
  compactedSource?: CompactedSource;
}

export interface CodeEntityRecord {
  id: string;
  /** Exact immutable collection that owns this entity. Optional on legacy records. */
  origin?: CodeEntityOrigin;
  handle: string;
  label: string;
  category: CodeEntityCategory;
  summary: string;
  sourceRanges: SourceRange[];
}

export interface ProjectRecord {
  repositories?: import("../repositories/repository").Repository[];
  schemaVersion: typeof SCHEMA_VERSION;
  id: string;
  name: string;
  defaultDomainProfileId?: import("../profiles/domainProfile").BuiltInDomainProfileId;
  /** Registered source bindings; legacy set bindings are migrated on load. */
  sources?: import("../diagrams/diagram").DiagramSourceBinding[];
  createdAt: string;
  updatedAt: string;
}

/** One immediate child of a live repository directory. */
export interface RepositoryEntry {
  path: string;
  name: string;
  kind: "directory" | "file";
}

/** A lazy view of one directory in a diagram-bound source corpus. */
export interface RepositoryDirectoryListing {
  directory: string;
  entries: RepositoryEntry[];
}

export interface DiagramSelectionBounds {
  startLine: number;
  endLine: number;
  startColumn: number;
  endColumn: number;
}

export interface DiagramElementMapping {
  id: string;
  entityId: string;
  /** Stable range identity; sourceRangeIndex remains for agent prompting and legacy maps. */
  sourceRangeId?: string;
  sourceRangeIndex: number;
  line: number;
  startColumn: number;
  endColumn: number;
}

/** Mapping coordinates anchored to one immutable diagram revision. */
export interface DiagramMappingSnapshot {
  artifactId: string;
  asciiSha256: string;
  mappings: DiagramElementMapping[];
}

export interface AgentProgress {
  status: "reading-context" | "generating" | "validating";
  message: string;
  model?: string;
  sessionId?: string;
}

export function assertSafeId(value: string, label = "id"): void {
  if (!/^[a-z0-9][a-z0-9-]{0,95}$/.test(value)) {
    throw new Error(`${label} is invalid: ${value}`);
  }
}

export function assertSourceRange(range: SourceRange): void {
  if (!range.path || range.path.startsWith("/") || range.path.split(/[\\/]/).includes("..")) {
    throw new Error(`source path must be repo-relative: ${range.path}`);
  }
  if (!Number.isInteger(range.startLine) || !Number.isInteger(range.endLine)) {
    throw new Error(`source lines must be integers for ${range.path}`);
  }
  if (range.startLine < 1 || range.endLine < range.startLine) {
    throw new Error(`invalid source range for ${range.path}`);
  }
  if (range.originalLines !== undefined && !Array.isArray(range.originalLines)) {
    throw new Error(`original source lines must be an array for ${range.path}`);
  }
  if (range.compactedSource !== undefined) {
    if (!(["low", "medium", "high"] as const).includes(range.compactedSource.level)) {
      throw new Error(`invalid source compaction level for ${range.path}`);
    }
    if (!Array.isArray(range.compactedSource.sections)) {
      throw new Error(`compacted source sections must be an array for ${range.path}`);
    }
    for (const section of range.compactedSource.sections) {
      if (section.kind !== "source" && section.kind !== "collapsed-comment") {
        throw new Error(`invalid compacted source section for ${range.path}`);
      }
      if (!Number.isInteger(section.startLine) || !Number.isInteger(section.endLine)) {
        throw new Error(`compacted source lines must be integers for ${range.path}`);
      }
      if (section.kind === "collapsed-comment" && !section.comment.trim()) {
        throw new Error(`collapsed source comment cannot be blank for ${range.path}`);
      }
      if (section.kind === "collapsed-comment" && !/^[\t\n\r\x20-\x7E]*$/.test(section.comment)) {
        throw new Error(`collapsed source call graph must contain only 7-bit ASCII for ${range.path}`);
      }
      if (section.kind === "collapsed-comment" && section.nodes !== undefined) {
        if (!Array.isArray(section.nodes) || section.nodes.length === 0) {
          throw new Error(`collapsed source call graph nodes cannot be empty for ${range.path}`);
        }
        const graphLineCount = section.comment.replace(/\r\n?/g, "\n").split("\n").length;
        const mappedGraphLines = new Set<number>();
        for (const node of section.nodes) {
          if (!Number.isInteger(node.graphLine) || node.graphLine < 1 || node.graphLine > graphLineCount) {
            throw new Error(`collapsed source node graph line is invalid for ${range.path}`);
          }
          if (mappedGraphLines.has(node.graphLine)) {
            throw new Error(`collapsed source node graph line is duplicated for ${range.path}`);
          }
          mappedGraphLines.add(node.graphLine);
          if (!Number.isInteger(node.startLine) || !Number.isInteger(node.endLine)
            || node.startLine < section.startLine || node.endLine > section.endLine
            || node.endLine < node.startLine) {
            throw new Error(`collapsed source node range is invalid for ${range.path}`);
          }
        }
      }
    }
  }
}

sources.domain/core/repositories/repository.ts:
import { z } from 'zod';

export interface Repository {
  id: string;
  name: string;
  /** Canonical Git common directory; linked worktrees share this identity. */
  identity: string;
  checkoutRoots: string[];
}
const sha = z.string().regex(/^(?:[a-f0-9]{40}|[a-f0-9]{64})$/);
export const repositoryContextSchema = z.object({
  repositoryId: z.string().min(1).max(200), commits: z.array(sha).max(2000), head: sha
}).strict().refine(context => new Set(context.commits).size === context.commits.length, 'Duplicate commits');
export type RepositoryContext = z.infer<typeof repositoryContextSchema>;

/** Canvas membership is stored once, on the canvas; repositories own that collection. */
export function repositoryGroups<T extends { repositoryId?: string }>(repositories: readonly Repository[], items: readonly T[]) {
  const groups = repositories.map(repository => ({ id: repository.id, name: repository.name, items: items.filter(item => item.repositoryId === repository.id) }));
  const known = new Set(repositories.map(repository => repository.id));
  const unassigned = items.filter(item => !item.repositoryId || !known.has(item.repositoryId));
  return [...groups, ...(unassigned.length ? [{ id: 'unassigned', name: 'Unassigned', items: unassigned }] : [])];
}

/** Legacy canvases with mixed/unknown source identities remain unassigned. */
export function inferRepositoryId(scene: import('../diagrams/lineGrid').LineGridScene, repositories: readonly Repository[]) {
  const identities = new Set(Object.values(scene.contents).flatMap(diagram => diagram.sourceContext.binding ? [diagram.sourceContext.binding.repositoryIdentity] : []));
  if (!identities.size) return repositories.length === 1 ? repositories[0].id : undefined;
  if (identities.size !== 1) return undefined;
  return repositories.find(repository => identities.has(repository.identity))?.id;
}

sources.domain/core/representations/catalogRules:
import { RevisionedDiagramService } from '../diagrams/diagramService';
import { DefaultCanvasHistoryService } from '../diagrams/canvasHistoryService';
import { DiagramRevisionEditor } from '../diagrams/diagramRevisionEditor';
import { documentFromHistory, validateCanvasHistory, stateKey } from '../diagrams/canvasHistory';
import { buildProjectionTree, validateProjection, type ProjectProjectionRecord } from "../diagrams/diagramProjection";
import { flattenGrid, resolveScene } from '../diagrams/lineGrid';
import { singleDiagramScene, projectCanvasSnapshot, sceneFromRevision, historyFromRevision, type SaveProjectDiagramInput } from "../diagrams/projectDiagramCanvas";
import {
  SCHEMA_VERSION,
  assertSafeId,
  assertSourceRange,
  type DiagramViewKind
} from "../records/domain";
import type { SaveProjectedTreeInput } from "./catalogCommands";
import { ProjectDiagramConflict } from "./errors";
import type {
  ProjectCorpusCompactionCatalogRecord,
  ProjectFileCompactionInput,
  ProjectFileCompactionRecord,
  ProjectRepresentationCatalogRecord,
  ProjectRepresentationRecord,
  ProjectRepresentationRevisionRecord
} from "./projectCatalog";
/** Clock and identifiers are supplied by the caller; transitions perform no I/O. */
export interface CatalogEnvironment {
  timestamp: string; representationId: string; revisionId: string;
  hash(value: string): string; stableId(prefix: string, ...parts: string[]): string;
}

export function saveProjection(catalog: ProjectRepresentationCatalogRecord, projectId: string, projection: ProjectProjectionRecord, environment: CatalogEnvironment) {

  validateProjection(projection, catalog);
  const existing = catalog.projections?.[projection.id];
  if (existing && JSON.stringify(existing) !== JSON.stringify(projection)) {
    throw new Error("Projection is immutable; save a new projection for changed links");
  }
  const next = { ...catalog, projections: { ...catalog.projections, [projection.id]: projection }, updatedAt: environment.timestamp };

  return { catalog: next, projection };

}

export function saveProjectedTree(catalog: ProjectRepresentationCatalogRecord, projectId: string, input: SaveProjectedTreeInput, environment: CatalogEnvironment) {
  if (!input || typeof input.name !== "string" || !input.name.trim() || input.name.length > 120
    || typeof input.ascii !== "string" || !input.ascii.trim() || input.ascii.length > 20000
    || !Array.isArray(input.links) || !input.links.length || input.links.length > 2000) {
    throw new Error("A named ASCII tree and projection links are required");
  }

  const source = catalog.representations[input.sourceRepresentationId];
  const sourceRevision = catalog.revisions[input.sourceRevisionId];
  if (!source || source.status !== "settled" || source.currentRevisionId !== input.sourceRevisionId
    || sourceRevision?.representationId !== source.id) {
    throw new ProjectDiagramConflict("Source diagram changed or is unavailable; regenerate its projection");
  }
  const linkedIds = new Set(input.links.flatMap(link => link.sourceEvidenceIds));
  const sourceDiagrams = Object.values(sceneFromRevision(sourceRevision).contents).filter(d =>
    Object.keys(d.sourceContext.evidence).some(id => linkedIds.has(id) || linkedIds.has(`${d.id}:${id}`)));
  const bindings = new Map(sourceDiagrams.flatMap(d => d.sourceContext.binding ? [[d.sourceContext.binding.sourceId, d.sourceContext.binding] as const] : []));
  if (bindings.size > 1) throw new Error("A projected diagram must select evidence from one source; create one diagram per source");
  const diagramSource = [...bindings.values()][0];
  const asciiSha256 = environment.hash(input.ascii);
  const mappingSignature = JSON.stringify(input.links);
  const targetId = input.targetRepresentationId ?? environment.stableId("representation", source.id, sourceRevision.id, input.name.trim(), asciiSha256, mappingSignature);
  // Mapping changes also produce a new immutable revision, even when the ASCII is unchanged.
  const revisionId = environment.stableId("representation-revision", targetId, asciiSha256, mappingSignature);
  const existingTarget = input.targetRepresentationId ? catalog.representations[input.targetRepresentationId] : undefined;
  if (input.targetRepresentationId && (!existingTarget || existingTarget.projectId !== projectId
    || existingTarget.status !== "settled" || existingTarget.representationKind !== "tree"
    || !Object.values(catalog.projections ?? {}).some((p) => p.sourceRepresentationId === source.id && p.targetRepresentationId === targetId)
    || (existingTarget.currentRevisionId !== input.expectedTargetRevisionId && existingTarget.currentRevisionId !== revisionId))) {
    throw new ProjectDiagramConflict("Call tree changed or is unavailable; regenerate against its current revision");
  }
  const timestamp = environment.timestamp;
  const revision: ProjectRepresentationRevisionRecord = {
    schemaVersion: 1, id: revisionId, projectId, representationId: targetId,
    revision: existingTarget ? (catalog.revisions[existingTarget.currentRevisionId]?.revision ?? 0) + 1 : 1,
    ascii: input.ascii, asciiSha256, representationKind: "tree",
    ...(diagramSource ? {source: diagramSource} : {}), evidence: structuredClone(Object.fromEntries(Object.entries(sourceRevision.evidence).filter(([id]) => linkedIds.has(id)))), mappings: [], createdAt: timestamp
  };
  const tree = buildProjectionTree(revision);
  const byLine = new Map(Object.values(tree.nodes).map((node) => [node.line, node]));
  const lines = input.ascii.split("\n");
  const links = input.links.map((link, linkIndex) => {
    if (!link || !Array.isArray(link.sourceEvidenceIds) || !link.sourceEvidenceIds.length
      || !Array.isArray(link.targetLines) || !link.targetLines.length) throw new Error("Invalid projection link");
    const targetNodeIds = link.targetLines.map((line) => {
      const node = byLine.get(line);
      if (!Number.isInteger(line) || !node) throw new Error(`Projection target row ${line} is not a tree node`);
      for (const evidenceId of link.sourceEvidenceIds) {
        const evidence = sourceRevision.evidence[evidenceId];
        if (!evidence) throw new Error(`Unknown projection source evidence: ${evidenceId}`);
        for (const range of evidence.sourceRanges) {
          const startColumn = lines[line - 1].lastIndexOf(node.text) + 1;
          revision.mappings.push({
            id: `projection-map-${linkIndex}-${line}-${evidenceId}-${range.id}`,
            evidenceId, sourceRangeId: range.id, line, startColumn, endColumn: startColumn + node.text.length - 1
          });
        }
      }
      return node.id;
    });
    return { sourceEvidenceIds: [...new Set(link.sourceEvidenceIds)], targetNodeIds: [...new Set(targetNodeIds)] };
  });
  const diagrams = new RevisionedDiagramService(), histories = new DefaultCanvasHistoryService();
  const scene = singleDiagramScene(revision.ascii);
  scene.contents = { ...scene.contents, overview: diagrams.create({ id: 'overview', revision: 0,
    ascii: revision.ascii, structureKind: 'tree', source: diagramSource, evidence: revision.evidence,
    mappings: revision.mappings.map(mapping => ({ id: mapping.id, entityId: mapping.evidenceId,
      sourceRangeId: mapping.sourceRangeId, sourceRangeIndex: revision.evidence[mapping.evidenceId].sourceRanges.findIndex(range => range.id === mapping.sourceRangeId),
      line: mapping.line, startColumn: mapping.startColumn, endColumn: mapping.endColumn })) }).diagram };
  revision.content = { kind: 'canvas-history', history: histories.exportContext(histories.openContext({ scene, edges: [], sections: {} }, {})) };
  delete revision.source;
  const representation: ProjectRepresentationRecord = {
    schemaVersion: 1, id: targetId, projectId, repositoryId: source.repositoryId, handle: targetId, name: input.name.trim(),
    viewKind: "call-graph", representationKind: "tree", status: "settled", currentRevisionId: revisionId,
    revisionIds: [...new Set([...(existingTarget?.revisionIds ?? []), revisionId])],
    createdAt: existingTarget?.createdAt ?? timestamp, updatedAt: timestamp
  };
  const projection: ProjectProjectionRecord = {
    id: environment.stableId("projection", sourceRevision.id, revisionId, JSON.stringify(links),
      ...(input.compactionProjection ? [JSON.stringify(input.compactionProjection)] : [])), projectId,
    name: input.name.trim(), sourceRepresentationId: source.id, sourceRevisionId: sourceRevision.id,
    targetRepresentationId: targetId, targetRevisionId: revisionId, match: "any", links
  };
  if (input.compactionProjection) {
    const { files, links: compactionLinks } = input.compactionProjection;
    if (!Array.isArray(files) || !Array.isArray(compactionLinks)) throw new Error("Invalid compaction projection");
    for (const file of files) {
      if (typeof file.ascii !== "string" || environment.hash(file.ascii) !== file.asciiSha256) {
        throw new Error("Compaction snapshot hash mismatch");
      }
    }
    projection.compactionProjection = {
      files: structuredClone(files).map(file => ({...file, ...(diagramSource ? {sourceId: diagramSource.sourceId} : {})})), links: compactionLinks.map((link) => {
        const node = byLine.get(link.callTreeLine);
        if (!node) throw new Error(`Unknown call-tree row ${link.callTreeLine}`);
        return { callTreeNodeId: node.id, file: link.file, treeLines: link.treeLines };
      })
    };
  }
  // Exact reimports are idempotent; never reset an independently edited target.
  if (catalog.projections?.[projection.id]) return { catalog, representation: catalog.representations[targetId], projection: catalog.projections[projection.id] };
  const next: ProjectRepresentationCatalogRecord = {
    ...catalog,
    representations: { ...catalog.representations, [targetId]: existingTarget ? representation : catalog.representations[targetId] ?? representation },
    revisions: { ...catalog.revisions, [revisionId]: catalog.revisions[revisionId] ?? revision },
    projections: { ...catalog.projections, [projection.id]: projection }, updatedAt: timestamp
  };
  validateProjection(projection, next);
  projectCanvasSnapshot(sceneFromRevision(revision));

  return { catalog: next, representation: next.representations[targetId], projection };

}

export function saveMappingDiagram(catalog: ProjectRepresentationCatalogRecord, projectId: string, input: SaveProjectDiagramInput, environment: CatalogEnvironment) {
  if (!input.history) throw new Error('Canvas history is required to save');
  if (input.projectId && input.projectId !== projectId) throw new Error("Diagram belongs to another Project");
  if (typeof input.name !== "string" || !input.name.trim() || input.name.length > 120) throw new Error("Diagram name must contain 1–120 characters");

  const current = input.representationId ? catalog.representations[input.representationId] : undefined;
  if (input.representationId && !current) throw new Error("Project diagram was not found");
  if (current?.repositoryId && input.repositoryId && current.repositoryId !== input.repositoryId) throw Error('Canvas repository ownership cannot change on save');
  if (current?.status === 'archived') throw new ProjectDiagramConflict('Canvas is archived');
  if (current && current.currentRevisionId !== input.expectedRevisionId) {
    const baseline = input.expectedRevisionId && catalog.revisions[input.expectedRevisionId];
    const latest = catalog.revisions[current.currentRevisionId];
    if (!baseline || baseline.representationId !== current.id || !latest) throw new ProjectDiagramConflict('Unknown canvas baseline');
    const bindings = (revision: ProjectRepresentationRevisionRecord) => {
      const history = historyFromRevision(revision);
      return history.snapshots[history.headId].diagramBindings;
    };
    try {
      new DiagramRevisionEditor({}, () => ({})).merge(bindings(baseline), bindings(latest),
        input.history?.snapshots[input.history.headId]?.diagramBindings ?? {});
    } catch (error) {
      throw new ProjectDiagramConflict(error instanceof Error ? error.message : 'MERGE_REQUIRED');
    }
    // The merge stub cannot reconcile concurrent composition/layout changes either.
    throw new ProjectDiagramConflict('CANVAS_CONFLICT: canvas advanced; reread before publishing');
  }
  const sourceId = current?.currentRevisionId ?? input.sourceRevisionId;
  const source = sourceId ? catalog.revisions[sourceId] : undefined;
  if (sourceId && !source) throw new Error("Source revision does not belong to this Project");
  if (input.history) {
    validateCanvasHistory(input.history);
    const projected = documentFromHistory(input.history);
    if (stateKey(projected.scene) !== stateKey(input.scene) || stateKey(projected.edges) !== stateKey(input.edges ?? []))
      throw new Error('Canvas history does not match save input');
    const savedHistory = source && historyFromRevision(source);
    if (savedHistory) for (const [id, revision] of Object.entries(input.history.diagramRevisions)) {
      const existing = savedHistory.diagramRevisions[id];
      if (existing && stateKey(existing) !== stateKey(revision)) throw new Error('Diagram revision is immutable');
    }
  }
  const scene = structuredClone(input.scene);
  const { ascii, mappings, evidence } = projectCanvasSnapshot(scene);
  const timestamp = environment.timestamp;
  const id = current?.id ?? environment.representationId;
  const revisionId = environment.revisionId;
  const visibleDiagrams = flattenGrid(resolveScene(scene)).filter(node => node.box.kind === 'diagram');
  const inferredKind = visibleDiagrams.length === 1 && visibleDiagrams[0].contentId
    ? scene.contents[visibleDiagrams[0].contentId].content.structure.kind : 'diagram';
  const history = input.history;
  const revision: ProjectRepresentationRevisionRecord = {
    schemaVersion: 1, id: revisionId, projectId, representationId: id,
    revision: (current?.revisionIds.length ?? 0) + 1,
    ascii, asciiSha256: environment.hash(ascii),
    content: { kind: "canvas-history", history: structuredClone(history) },
    representationKind: current?.representationKind ?? source?.representationKind ?? inferredKind,
    evidence, mappings, ...(source?.provenance ? { provenance: source.provenance } : {}), createdAt: timestamp
  };
  const representation: ProjectRepresentationRecord = {
    schemaVersion: 1, id, projectId, repositoryId: input.repositoryId ?? current?.repositoryId ?? (source ? catalog.representations[source.representationId]?.repositoryId : undefined), handle: current?.handle ?? id, name: input.name.trim(),
    viewKind: current?.viewKind ?? "diagram", representationKind: revision.representationKind,
    status: "settled", currentRevisionId: revisionId, revisionIds: [...(current?.revisionIds ?? []), revisionId],
    createdAt: current?.createdAt ?? timestamp, updatedAt: timestamp
  };
  const next = {
    ...catalog, representations: { ...catalog.representations, [id]: representation },
    revisions: { ...catalog.revisions, [revisionId]: revision }, updatedAt: timestamp
  };

  return { catalog: next, representation };

}

export function upsertFileCompaction(catalog: ProjectCorpusCompactionCatalogRecord, projectId: string, input: ProjectFileCompactionInput, environment: CatalogEnvironment) {
  const profile = input.profile ?? { id: "multilevel-lifecycle", version: 1 };
  assertSafeId(profile.id, "compaction profile id");
  if (!Number.isInteger(profile.version) || profile.version < 1) {
    throw new Error("compaction profile version must be a positive integer");
  }
  assertSourceRange({
    path: input.path,
    startLine: input.startLine,
    endLine: input.endLine,
    originalLines: input.originalLines,
    compactedSource: input.compactedSource
  });
  const expectedLineCount = input.endLine - input.startLine + 1;
  if (input.originalLines.length !== expectedLineCount) {
    throw new Error(`compaction source snapshot length does not match ${input.path}`);
  }
  const sourceSha256 = environment.hash(input.originalLines.join("\n"));
  const id = environment.stableId(
    "compaction",
    projectId,
    input.sourceId ?? "unbound",
    input.path,
    sourceSha256,
    profile.id,
    String(profile.version)
  );

  const existing = catalog.compactions[id];
  const timestamp = environment.timestamp;
  const proposed: ProjectFileCompactionRecord = {
    schemaVersion: SCHEMA_VERSION,
    id,
    projectId,
    path: input.path, ...(input.sourceId ? {sourceId:input.sourceId} : {}),
    ...(input.sourceRevision ? { sourceRevision: input.sourceRevision } : {}),
    sourceSha256,
    startLine: input.startLine,
    endLine: input.endLine,
    originalLines: [...input.originalLines],
    compactedSource: input.compactedSource,
    profile,
    ...(input.provenance ? { provenance: input.provenance } : {}),
    createdAt: existing?.createdAt ?? timestamp,
    updatedAt: existing?.updatedAt ?? timestamp
  };
  if (existing) {
    const comparableExisting = { ...existing, updatedAt: undefined };
    const comparableInput = { ...proposed, updatedAt: undefined };
    if (JSON.stringify(comparableExisting) !== JSON.stringify(comparableInput)) {
      throw new Error(`conflicting Project compaction: ${id}`);
    }
  }
  const compaction = existing ?? proposed;
  const activeByPath = { ...catalog.activeByPath };
  if (input.makeActive !== false) activeByPath[JSON.stringify([input.sourceId ?? null, input.path])] = id;
  const next: ProjectCorpusCompactionCatalogRecord = {
    ...catalog,
    activeByPath,
    compactions: { ...catalog.compactions, [id]: compaction },
    updatedAt: timestamp
  };

  return { catalog: next, compaction };

}

export function archiveRepresentation(catalog: ProjectRepresentationCatalogRecord, projectId: string, representationId: string, environment: CatalogEnvironment) {

  const representation = catalog.representations[representationId];
  if (!representation) throw new Error(`unknown Project representation: ${representationId}`);
  if (representation.status === "archived") return catalog;
  const activeByKind = { ...catalog.activeByKind };
  for (const [viewKind, activeId] of Object.entries(activeByKind)) {
    if (activeId === representationId) delete activeByKind[viewKind as DiagramViewKind];
  }
  const timestamp = environment.timestamp;
  const next: ProjectRepresentationCatalogRecord = {
    ...catalog,
    activeByKind,
    representations: {
      ...catalog.representations,
      [representationId]: { ...representation, status: "archived", updatedAt: timestamp }
    },
    updatedAt: timestamp
  };

  return next;

}

