import type {
  CodeEntityCategory,
  CompactedSource,
  DiagramViewKind,
  SourceRange
} from "../records/domain";

export interface ProjectCompactionProvenance {
  diagramSetId?: string;
  codeEntitiesSetId?: string;
  codeEntityId?: string;
  sourceRangeId?: string;
}

/** One immutable full-file or ranged compaction shared by every generation session in a Project. */
export interface ProjectFileCompactionRecord {
  schemaVersion: 1;
  id: string;
  projectId: string;
  sourceId?: string;
  path: string;
  sourceRevision?: string;
  sourceSha256: string;
  startLine: number;
  endLine: number;
  originalLines: string[];
  compactedSource: CompactedSource;
  profile: {
    id: string;
    version: number;
  };
  provenance?: ProjectCompactionProvenance;
  createdAt: string;
  updatedAt: string;
}

export interface ProjectCorpusCompactionCatalogRecord {
  schemaVersion: 1;
  projectId: string;
  /** The current compaction for a live corpus path; historical source revisions remain addressable. */
  activeByPath: Record<string, string>;
  compactions: Record<string, ProjectFileCompactionRecord>;
  createdAt: string;
  updatedAt: string;
}

export interface ProjectFileCompactionInput {
  sourceId?: string;
  path: string;
  sourceRevision?: string;
  startLine: number;
  endLine: number;
  originalLines: string[];
  compactedSource: CompactedSource;
  profile?: {
    id: string;
    version: number;
  };
  provenance?: ProjectCompactionProvenance;
  makeActive?: boolean;
}

export interface ProjectRepresentationEvidenceRange {
  id: string;
  path: string;
  startLine: number;
  endLine: number;
  symbol?: string;
  originalLines: string[];
  /** Resolves presentation through the Project corpus catalog rather than a generation session. */
  compactionId?: string;
}

export interface ProjectRepresentationEvidenceRecord {
  sourceId?: string;
  id: string;
  handle: string;
  label: string;
  category: CodeEntityCategory;
  summary: string;
  sourceRanges: ProjectRepresentationEvidenceRange[];
}

export interface ProjectRepresentationMappingRecord {
  id: string;
  evidenceId: string;
  sourceRangeId: string;
  line: number;
  startColumn: number;
  endColumn: number;
}

export interface ProjectRepresentationRevisionRecord {
  schemaVersion: 1;
  id: string;
  projectId: string;
  representationId: string;
  revision: number;
  ascii: string;
  asciiSha256: string;
  /** Absent legacy content is a single ASCII diagram. */
  content?: import("../diagrams/projectDiagramCanvas").ProjectDiagramContent;
  representationKind: "tree" | "diagram";
  source?: import("../diagrams/diagram").DiagramSourceBinding;
  evidence: Record<string, ProjectRepresentationEvidenceRecord>;
  mappings: ProjectRepresentationMappingRecord[];
  provenance?: {
    diagramSetId: string;
    artifactId: string;
  };
  createdAt: string;
}

export interface ProjectRepresentationRecord {
  repositoryId?: string;
  schemaVersion: 1;
  id: string;
  projectId: string;
  handle: string;
  name: string;
  viewKind: DiagramViewKind;
  representationKind: "tree" | "diagram";
  status: "settled" | "archived";
  currentRevisionId: string;
  revisionIds: string[];
  createdAt: string;
  updatedAt: string;
}

export interface ProjectRepresentationCatalogRecord {
  repositoryOwnershipVersion?: 1;
  schemaVersion: 1;
  projectId: string;
  activeByKind: Partial<Record<DiagramViewKind, string>>;
  representations: Record<string, ProjectRepresentationRecord>;
  revisions: Record<string, ProjectRepresentationRevisionRecord>;
  /** Committed atomically with every canvas affected by an accepted proposal. */
  changeSessionAcceptances?: Record<string, import('./changeAcceptance').ChangeSessionAcceptance>;
  /** Revision-pinned correspondences to complementary project diagrams. */
  projections?: Record<string, import("../diagrams/diagramProjection").ProjectProjectionRecord>;
  createdAt: string;
  updatedAt: string;
}

export interface PromoteProjectRepresentationInput {
  diagramSetId: string;
  diagramId: string;
  representationId?: string;
  expectedRevisionId?: string;
  makeActive?: boolean;
}

export function sourceRangeFromProjectEvidence(
  range: ProjectRepresentationEvidenceRange,
  compaction?: ProjectFileCompactionRecord
): SourceRange {
  return {
    id: range.id,
    path: range.path,
    startLine: range.startLine,
    endLine: range.endLine,
    ...(range.symbol ? { symbol: range.symbol } : {}),
    originalLines: [...range.originalLines],
    ...(compaction ? { compactedSource: compaction.compactedSource } : {})
  };
}

sources.domain/mapping/changes/diagramChangeSess:
import { diffTreeSummary, diffTreeSummarySchema, validateDiffTree, type ChangeSessionDiffTree, type DiffTreeSummary } from './diffTree';
import { repositoryContextSchema } from '../../core/repositories/repository';
import { CanvasHistory, validateCanvasHistory, type CanvasHistoryRecord } from '../workspace/canvasHistory';
import { z } from 'zod';
import { diagramMigrationSchema, type DiagramMigration } from './diagramMigration';
import type { MappingGridDocument } from '../workspace/mappingGrid';
import type { MappingCanvasState } from '../workspace/mappingWorkspace';
import { deserializeWorkspace } from '../workspace/mappingWorkspaceCodec';
import type { ChangeSessionAcceptance } from '../../core/representations/changeAcceptance';

export const changeId = z.string().min(1).max(200).regex(/^[a-zA-Z0-9_.:-]+$/).refine(id => !['__proto__','constructor','prototype'].includes(id));
export const diagramChangeSchema = z.object({
  id: changeId, title: z.string().trim().min(1).max(200), type: z.union([z.literal(1), z.literal(2), z.literal(3), z.literal(4)]),
  reasons: z.array(z.enum(['1a', '1b'])).default([]), documentId: changeId, nodeId: changeId.optional(),
  dependsOn: z.array(changeId).max(100).default([])
}).strict();
export type DiagramChange = z.infer<typeof diagramChangeSchema>;
export interface ChangeDocumentState { nodeOrigins?: Record<string, string>; document: MappingGridDocument; canvas: MappingCanvasState }
export interface ChangeSessionDocument {
  repositoryId?: string;
  history?: CanvasHistoryRecord;
  id: string; name: string; representationId?: string; savedRevisionId?: string; capturedVersion?: number;
  baseline: ChangeDocumentState | null;
  proposed: ChangeDocumentState;
  version: number;
  past: ChangeDocumentState[];
  future: ChangeDocumentState[];
}
export interface DiagramChangeSession {
  /** Absent on legacy sessions whose historical Git context is unknown. */
  repositoryId?: string; commits?: string[]; head?: string;
  diffTree?: ChangeSessionDiffTree;
  schemaVersion: 1; id: string; projectId: string; title: string; description: string;
  status: 'draft' | 'ready' | 'accepted' | 'archived'; version: number; createdAt: string; updatedAt: string;
  acceptance?: ChangeSessionAcceptance;
  documents: ChangeSessionDocument[]; changes: DiagramChange[]; migrations?: DiagramMigration[];
  receipts: Record<string, { signature: string; result: unknown }>;
}
export type ChangeSessionSummary = Omit<DiagramChangeSession, 'documents' | 'receipts' | 'diffTree'> & {
  diffTree?: DiffTreeSummary;
  documents: Pick<ChangeSessionDocument, 'id' | 'name' | 'representationId' | 'repositoryId' | 'version'>[];
};
export type ChangePreviewDocument = Omit<ChangeSessionDocument, 'history' | 'past' | 'future'>;
export type ChangeSessionPreview = ChangeSessionSummary & { document: ChangePreviewDocument };
const checkpoint = z.object({ revisionId: changeId, checkpointId: changeId }).strict();
const acceptance = z.object({ changeSessionId: changeId, sessionVersion: z.number().int().nonnegative(), requestId: z.string().min(1),
  acceptedAt: z.string(), changeIds: z.array(changeId), documents: z.array(z.object({ documentId: changeId, representationId: changeId,
    before: checkpoint.nullable(), after: checkpoint, proposedCheckpointId: changeId }).strict()) }).strict();
/** Read list metadata without restoring document references, histories, or replay receipts. */
export function validateChangeSessionSummary(input: unknown): ChangeSessionSummary {
  const summary = z.object({
    diffTree: diffTreeSummarySchema.optional(),
    repositoryId: changeId.optional(), commits: repositoryContextSchema.shape.commits.optional(), head: repositoryContextSchema.shape.head.optional(),
    schemaVersion: z.literal(1), id: changeId, projectId: changeId, title: z.string().min(1).max(200), description: z.string().max(100000),
    status: z.enum(['draft', 'ready', 'accepted', 'archived']), acceptance: acceptance.optional(),
    version: z.number().int().nonnegative(), createdAt: z.string(), updatedAt: z.string(),
    changes: z.array(diagramChangeSchema).max(2000), migrations: z.array(diagramMigrationSchema).max(1000).default([]),
    documents: z.array(z.object({ id: changeId, name: z.string().min(1).max(200), repositoryId: changeId.optional(), representationId: changeId.optional(),
      version: z.number().int().nonnegative() })).max(100)
  }).parse(input);
  validateRepositoryContext(summary);
  if ((summary.status === 'accepted') !== !!summary.acceptance || summary.acceptance && summary.acceptance.changeSessionId !== summary.id)
    throw new Error('Invalid change-session acceptance');
  if (new Set(summary.documents.map(doc => doc.id)).size !== summary.documents.length) throw new Error('Duplicate change-session document');
  return summary;
}
export function summarizeChangeSession(session: DiagramChangeSession): ChangeSessionSummary {
  const { receipts: _, documents, diffTree, ...summary } = session;
  return { ...summary, ...(diffTree ? { diffTree: diffTreeSummary(diffTree) } : {}), documents: documents.map(({ id, name, representationId, repositoryId, version }) => ({ id, name, representationId, repositoryId, version })) };
}
export function validateChangeSession(input: unknown): DiagramChangeSession {
  const state = z.custom<ChangeDocumentState>(value => !!value && typeof value === 'object' && 'document' in value && 'canvas' in value);
  const parsed = z.object({
    diffTree: z.custom<ChangeSessionDiffTree>().optional(),
    repositoryId: changeId.optional(), commits: repositoryContextSchema.shape.commits.optional(), head: repositoryContextSchema.shape.head.optional(),
    schemaVersion: z.literal(1), id: changeId, projectId: changeId, title: z.string().min(1).max(200), description: z.string().max(100000),
    status: z.enum(['draft','ready','accepted','archived']), acceptance: acceptance.optional(), version: z.number().int().nonnegative(), createdAt: z.string(), updatedAt: z.string(),
    documents: z.array(z.object({ history: z.custom<CanvasHistoryRecord>().optional(), id: changeId, name: z.string().min(1).max(200), repositoryId: changeId.optional(), representationId: changeId.optional(), savedRevisionId: changeId.optional(),
      capturedVersion: z.number().int().nonnegative().optional(), baseline: state.nullable(), proposed: state, version: z.number().int().nonnegative(),
      past: z.array(state).max(50), future: z.array(state).max(50) }).strict()).max(100),
    changes: z.array(diagramChangeSchema).max(2000), migrations: z.array(diagramMigrationSchema).max(1000).default([]),
    receipts: z.record(z.string(), z.object({ signature: z.string(), result: z.unknown() }))
  }).strict().parse(input);
  validateRepositoryContext(parsed);
  if (parsed.diffTree) {
    validateDiffTree(parsed.diffTree);
    if (!parsed.repositoryId || parsed.diffTree.hunks.some(hunk => hunk.repositoryId !== parsed.repositoryId || !parsed.commits?.includes(hunk.commit)))
      throw Error('DiffTree hunks belong to another repository or commit selection');
  }
  if ((parsed.status === 'accepted') !== !!parsed.acceptance || parsed.acceptance && parsed.acceptance.changeSessionId !== parsed.id)
    throw new Error('Invalid change-session acceptance');
  const ids = new Set<string>();
  for (const doc of parsed.documents) {
    if (ids.has(doc.id)) throw new Error('Duplicate change-session document');
    ids.add(doc.id);
    if (doc.history) { validateCanvasHistory(doc.history); new CanvasHistory(doc.proposed.document, doc.proposed.canvas, doc.history); }
    for (const snapshot of [doc.baseline, doc.proposed, ...doc.past, ...doc.future]) if (snapshot) {
      deserializeWorkspace({ schemaVersion: 3, projectId: parsed.projectId, documents: [{ representationId: doc.id,
        name: doc.name, savedName: doc.name, revisionId: doc.savedRevisionId ?? 'session-baseline', savedScene: JSON.stringify(snapshot.document.scene),
        savedEdges: JSON.stringify(snapshot.document.edges), ...snapshot }] });
    }
  }
  return parsed;
}

function validateRepositoryContext(session: { repositoryId?: string; commits?: string[]; head?: string }) {
  if (session.repositoryId !== undefined || session.commits !== undefined || session.head !== undefined)
    repositoryContextSchema.parse({ repositoryId: session.repositoryId, commits: session.commits, head: session.head });
}

sources.domain/mapping/changes/diagramContentDif:
import type { DiagramContent } from '../../core/diagrams/diagramContent';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { matchDiagramNodes } from './diagramNodeMatcher';
import { orderedIndices } from './orderedIndices';

export type DiffStatus = 'added' | 'removed' | 'modified';
export interface NodeDiff { status?: DiffStatus; moved?: boolean; containsChanges?: boolean }
export interface DiagramDiffSide {
  nodes: Map<string, NodeDiff>;
  /** Unparsed text only, keyed by its original 1-based source line. */
  lines: Map<number, DiffStatus>;
}
export interface DiagramContentDiff {
  original: DiagramDiffSide; proposed: DiagramDiffSide;
  modifications: { original: ModifiedText; proposed: ModifiedText }[];
  /** Baseline-only text inserted before a proposed source line, without live anchors. */
  removals: { text: string; beforeLine: number; ancestorIds: string[]; spans: { start: number; end: number; contentNodeId?: string }[] }[];
  counts: { added: number; removed: number; modified: number; moved: number };
}
export interface ModifiedText { contentNodeId?: string; sourceLine: number; text: string }

/** Rendering-only correspondence. Never use these heuristic matches for edge anchors. */
export function diffDiagramContent(before: DiagramContent | undefined, after: DiagramContent | undefined,
  origins: Readonly<Record<string, string>> = {}): DiagramContentDiff {
  const result: DiagramContentDiff = { original: { nodes: new Map(), lines: new Map() },
    proposed: { nodes: new Map(), lines: new Map() }, modifications: [], removals: [], counts: { added: 0, removed: 0, modified: 0, moved: 0 } };
  if (before?.ascii === after?.ascii) return result;
  const index = (content?: DiagramContent) => {
    const lines = content?.ascii.split('\n') ?? [];
    const nodes = (content ? diagramContentNodes(content) : []).filter(n =>
      lines[n.line - 1]?.slice(n.startColumn - 1, n.endColumn) === n.label);
    return { lines, nodes, byId: new Map(nodes.map(n => [n.id, n])) };
  };
  const a = index(before), b = index(after);
  const { forward, reverse } = matchDiagramNodes(a.nodes, b.nodes, origins);
  const children = (side: typeof a, parent?: string) => parent
    ? (side.byId.get(parent)?.childIds ?? []).flatMap(id => side.byId.has(id) ? [side.byId.get(id)!] : [])
    : side.nodes.filter(n => !n.parentId || !side.byId.has(n.parentId));

  const update = (side: DiagramDiffSide, id: string, value: NodeDiff) => side.nodes.set(id, { ...side.nodes.get(id), ...value });
  for (const n of a.nodes) if (!forward.has(n.id)) { update(result.original, n.id, { status: 'removed' }); result.counts.removed++; }
  for (const n of b.nodes) if (!reverse.has(n.id)) { update(result.proposed, n.id, { status: 'added' }); result.counts.added++; }
  const moved = new Set<string>();
  for (const [oldId, nextId] of forward) {
    const old = a.byId.get(oldId)!, next = b.byId.get(nextId)!;
    if (old.label !== next.label) {
      result.modifications.push({ original: { contentNodeId: oldId, sourceLine: old.line, text: old.label },
        proposed: { contentNodeId: nextId, sourceLine: next.line, text: next.label } });
      update(result.original, oldId, { status: 'modified' }); update(result.proposed, nextId, { status: 'modified' }); result.counts.modified++;
    }
    if (old.parentId ? !forward.has(old.parentId) || forward.get(old.parentId) !== next.parentId : !!next.parentId) moved.add(oldId);
  }
  for (const parent of [undefined, ...a.nodes.map(n => n.id)]) {
    const left = children(a, parent), targetParent = parent ? forward.get(parent) : undefined;
    if (parent && !targetParent) continue;
    const positions = new Map(children(b, targetParent).map((n, i) => [n.id, i]));
    const matched = left.flatMap(n => { const j = positions.get(forward.get(n.id) ?? ''); return j === undefined ? [] : [{ id: n.id, j }]; });
    const stable = orderedIndices(matched.map(n => n.j));
    matched.forEach((n, i) => { if (!stable.has(i)) moved.add(n.id); });
  }
  for (const old of moved) {
    update(result.original, old, { moved: true }); update(result.proposed, forward.get(old)!, { moved: true }); result.counts.moved++;
  }
  const ancestors = (side: typeof a, output: DiagramDiffSide, other: DiagramDiffSide, matches: Map<string, string>) => {
    for (const [id, diff] of [...output.nodes]) if (diff.status || diff.moved) {
      let parent = side.byId.get(id)?.parentId;
      while (parent) {
        update(output, parent, { containsChanges: true });
        const peer = matches.get(parent); if (peer) update(other, peer, { containsChanges: true });
        parent = side.byId.get(parent)?.parentId;
      }
    }
  };
  ancestors(a, result.original, result.proposed, forward); ancestors(b, result.proposed, result.original, reverse);

  // Text without a structural label still participates in review. Unique unchanged
  // lines anchor ordered gaps; equal repeated blocks remain unchanged.
  const loose = (side: typeof a) => {
    const occupied = new Set(side.nodes.map(n => n.line));
    return side.lines.flatMap((text, i) => !occupied.has(i + 1) && /[^\s|+`\\/-]/.test(text) ? [{ text, line: i + 1 }] : []);
  };
  const oldText = loose(a), newText = loose(b);
  const lineMatches = new Map<number, number>();
  for (const [oldId, newId] of forward) lineMatches.set(a.byId.get(oldId)!.line, b.byId.get(newId)!.line);
  const lineDiff = (left: typeof oldText, right: typeof newText) => {
    let start = 0, endA = left.length, endB = right.length;
    while (start < endA && start < endB && left[start].text === right[start].text) {
      lineMatches.set(left[start].line, right[start].line); start++;
    }
    while (endA > start && endB > start && left[endA - 1].text === right[endB - 1].text) { endA--; endB--; lineMatches.set(left[endA].line, right[endB].line); }
    const l = left.slice(start, endA), r = right.slice(start, endB);
    const oldPositions = new Map<string, number[]>(), newPositions = new Map<string, number[]>();
    l.forEach((n, i) => oldPositions.set(n.text, [...(oldPositions.get(n.text) ?? []), i]));
    r.forEach((n, i) => newPositions.set(n.text, [...(newPositions.get(n.text) ?? []), i]));
    const anchors = l.flatMap((n, i) => oldPositions.get(n.text)?.length === 1 && newPositions.get(n.text)?.length === 1 ? [{ i, j: newPositions.get(n.text)![0] }] : []);
    const stable = orderedIndices(anchors.map(n => n.j)), ordered = anchors.filter((_, i) => stable.has(i));
    if (ordered.length) {
      let i = 0, j = 0;
      for (const n of ordered) { lineMatches.set(l[n.i].line, r[n.j].line); lineDiff(l.slice(i, n.i), r.slice(j, n.j)); i = n.i + 1; j = n.j + 1; }
      lineDiff(l.slice(i), r.slice(j)); return;
    }
    const modified = l.length === 1 && r.length === 1;
    if (modified) lineMatches.set(l[0].line, r[0].line);
    if (modified) result.modifications.push({ original: { sourceLine: l[0].line, text: l[0].text },
      proposed: { sourceLine: r[0].line, text: r[0].text } });
    for (const n of l) result.original.lines.set(n.line, modified ? 'modified' : 'removed');
    for (const n of r) result.proposed.lines.set(n.line, modified ? 'modified' : 'added');
    result.counts.modified += Number(modified);
    if (!modified) { result.counts.removed += l.length; result.counts.added += r.length; }
  };
  lineDiff(oldText, newText);
  const foldedText = (side: typeof a, output: DiagramDiffSide, other: DiagramDiffSide, matches: Map<string, string>) => {
    for (const n of side.nodes) if ([...output.lines.keys()].some(line => n.foldRanges.some(range => line >= range.startLine && line <= range.endLine))) {
      update(output, n.id, { containsChanges: true });
      const peer = matches.get(n.id); if (peer) update(other, peer, { containsChanges: true });
    }
  };
  foldedText(a, result.original, result.proposed, forward); foldedText(b, result.proposed, result.original, reverse);
  // Place deleted text near surviving context. A surviving ancestor bounds the
  // search so a deleted final child stays inside its branch, even after a move.
  const rows = new Map<number, typeof a.nodes>();
  for (const node of a.nodes) rows.set(node.line, [...(rows.get(node.line) ?? []), node]);
  const anchors = [...lineMatches].sort(([left], [right]) => left - right);
  for (let line = 1; line <= a.lines.length; line++) {
    const nodes = rows.get(line) ?? [];
    const removed = nodes.filter(node => result.original.nodes.get(node.id)?.status === 'removed');
    if (!removed.length && result.original.lines.get(line) !== 'removed') continue;
    // For multi-column diagrams, do not repeat surviving labels on the ghost row.
    const chars = a.lines[line - 1].split('');
    for (const node of nodes) if (!removed.includes(node)) chars.fill(' ', node.startColumn - 1, node.endColumn);
    const containing = a.nodes.filter(node => node.foldRanges.some(range => line >= range.startLine && line <= range.endLine)
      && node.line !== line && forward.has(node.id));
    const ancestorIds = containing.map(node => forward.get(node.id)!);
    const parent = containing.sort((left, right) => right.line - left.line)[0];
    const parentEnd = parent ? Math.max(parent.line, ...parent.foldRanges.map(range => range.endLine)) : a.lines.length;
    const next = anchors.find(([oldLine]) => oldLine > line && oldLine <= parentEnd);
    const proposedParent = parent && b.byId.get(forward.get(parent.id)!);
    const previous = anchors.filter(([oldLine]) => oldLine < line).at(-1);
    const beforeLine = next?.[1] ?? (proposedParent
      ? Math.max(proposedParent.line, ...proposedParent.foldRanges.map(range => range.endLine)) + 1
      : previous ? previous[1] + 1 : b.lines.length + 1);
    const text = chars.join('').trimEnd();
    const spans = removed.length ? removed.map(node => ({ start: node.startColumn - 1, end: node.endColumn, contentNodeId: node.id }))
      : [{ start: text.length - text.trimStart().length, end: text.length }];
    result.removals.push({ text, beforeLine, ancestorIds, spans });
  }
  return result;
}

import { z } from 'zod';
import { diagramContentNodes } from '../../core/diagrams/diagramContentNodes';
import { findBox } from '../workspace/canvasDisplayNode';
import type { ChangePreviewDocument } from './diagramChangeSession';

const id = z.string().min(1).max(200);
export const migrationEndpointSchema = z.object({
  documentId: id, displayNodeId: id, contentNodeId: z.string().min(1).max(1000), revisionId: id,
  snapshot: z.enum(['baseline', 'proposed']), scope: z.enum(['node', 'subtree']).default('node')
}).strict();
export const diagramMigrationSchema = z.object({
  id, title: z.string().trim().min(1).max(200), description: z.string().trim().min(1).max(4000),
  kind: z.enum(['code-organization', 'feature-ownership']),
  source: migrationEndpointSchema,
  destination: migrationEndpointSchema.extend({ snapshot: z.literal('proposed') })
}).strict();
export type MigrationEndpoint = z.infer<typeof migrationEndpointSchema>;
export type DiagramMigration = z.infer<typeof diagramMigrationSchema>;
export type MigrationRole = 'source' | 'destination';

/** Resolve only exact persisted identities. Heuristic diff matches are not endpoint identities. */
export function resolveMigrationEndpoint(doc: ChangePreviewDocument | undefined, endpoint: MigrationEndpoint) {
  if (!doc || doc.id !== endpoint.documentId) throw Error('Unknown migration document');
  const state = doc[endpoint.snapshot];
  const box = state && endpoint.displayNodeId.startsWith('grid:')
    ? findBox(state.document.scene.root, endpoint.displayNodeId.slice(5)) : undefined;
  if (!state || box?.kind !== 'diagram') throw Error('Migration diagram is missing');
  const content = state.document.scene.contents[box.contentId].content;
  if (content.revisionId !== endpoint.revisionId) throw Error('Migration endpoint revision is stale; reread and update the endpoint');
  const nodes = diagramContentNodes(content), node = nodes.find(n => n.id === endpoint.contentNodeId);
  if (!node) throw Error('Migration content node is stale; reread and update the endpoint');
  const selected = new Set([node.id]);
  if (endpoint.scope === 'subtree') {
    const add = (id: string) => { for (const child of nodes.find(n => n.id === id)?.childIds ?? []) { selected.add(child); add(child); } };
    add(node.id);
  }
  return { content, node, nodes: nodes.filter(n => selected.has(n.id)) };
}

export function migrationIssues(documents: readonly ChangePreviewDocument[], migrations: readonly DiagramMigration[]) {
  const issues: { migrationId: string; role: MigrationRole; message: string }[] = [];
  const ids = new Set<string>();
  for (const migration of migrations) {
    if (ids.has(migration.id)) issues.push({ migrationId: migration.id, role: 'source', message: 'Duplicate migration ID' });
    ids.add(migration.id);
    for (const role of ['source', 'destination'] as const) {
      try { resolveMigrationEndpoint(documents.find(doc => doc.id === migration[role].documentId), migration[role]); }
      catch (error) { issues.push({ migrationId: migration.id, role, message: (error as Error).message }); }
    }
  }
  return issues;
}

