import { createHash } from 'node:crypto';
import { execFileAsync } from './shared';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import { parseGitFileDiff, type GitDiffHunk } from '../../../domain/core/diffs/gitDiffHunk';

const MAX_BYTES = 8 * 1024 * 1024;
/** Immutable first-parent commit diffs. Renames are represented as deletion/addition. */
export async function captureGitHunks(root: string, context: RepositoryContext): Promise<GitDiffHunk[]> {
  const git = async (...args: string[]) => (await execFileAsync('git', ['--literal-pathspecs', '-C', root, ...args], {
    encoding: 'utf8', maxBuffer: MAX_BYTES, timeout: 15000, env: { ...process.env, LC_ALL: 'C', GIT_NO_REPLACE_OBJECTS: '1' }
  })).stdout;
  const hunks: GitDiffHunk[] = [];
  let bytes = 0;
  for (const commit of context.commits) {
    // Read the actual object: rev-list treats a shallow boundary as a root.
    const object = await git('cat-file', 'commit', commit);
    const headers = object.split('\n\n', 1)[0];
    const parent = headers.match(/^parent ([a-f0-9]+)$/m)?.[1] ?? null;
    const base = parent ?? createHash(commit.length === 64 ? 'sha256' : 'sha1').update('tree 0\0').digest('hex');
    const entries = (await git('diff', '--no-ext-diff', '--no-textconv', '--no-renames', '--name-status', '-z', base, commit, '--')).split('\0');
    entries.pop();
    for (let index = 0; index < entries.length; index += 2) {
      const status = entries[index], file = entries[index + 1];
      if (!file || !['A', 'M', 'D', 'T'].includes(status)) throw Error('Unsupported Git diff entry');
      const patch = await git('-c', 'core.quotePath=true', 'diff', '--no-ext-diff', '--no-textconv', '--no-renames', '--no-color',
        '--full-index', '--diff-algorithm=myers', '--no-indent-heuristic', '--unified=3', '--inter-hunk-context=0', '--src-prefix=a/', '--dst-prefix=b/', base, commit, '--', file);
      bytes += Buffer.byteLength(patch);
      if (bytes > MAX_BYTES) throw Error('Diff exceeds 8 MiB; select fewer commits');
      hunks.push(...parseGitFileDiff({ repositoryId: context.repositoryId, commit, parent, path: file, status: status as GitDiffHunk['status'] }, patch));
      if (hunks.length > 2000) throw Error('Diff exceeds 2000 hunks; select fewer commits');
    }
  }
  return hunks;
}

import { captureGitHunks } from './repositoryHunks';
import type { RepositoryContext } from '../../../domain/core/repositories/repository';
import path from 'node:path';
import { createHash } from 'node:crypto';
import type { RepositoryRegistry } from '../../../application/core/ports/repositoryRegistry';
import type { Repository } from '../../../domain/core/repositories/repository';
import { repositoryContextSchema } from '../../../domain/core/repositories/repository';
import type { ProjectRecord } from '../../../domain/core/records/domain';
import { discoverRepository, execFileAsync, readJsonIfExists, writeJsonAtomic } from './shared';

const queues = new Map<string, Promise<unknown>>();
export class GitRepositoryRegistry implements RepositoryRegistry {
  private readonly file: string;
  constructor(storeRoot: string, private readonly checkoutRoot: string) { this.file = path.join(storeRoot, 'project.json'); }
  private async serial<T>(run: () => Promise<T>): Promise<T> {
    const next = (queues.get(this.file) ?? Promise.resolve()).catch(() => {}).then(run);
    queues.set(this.file, next);
    try { return await next; } finally { if (queues.get(this.file) === next) queues.delete(this.file); }
  }
  private async project() {
    const project = await readJsonIfExists<ProjectRecord>(this.file);
    if (!project) throw Error('Project is not initialized');
    return project;
  }
  private async discover(root: string, name?: string): Promise<Repository> {
    const location = await discoverRepository(root);
    return { id: `repo-${createHash('sha256').update(location.repositoryIdentity).digest('hex').slice(0, 24)}`,
      name: name?.trim() || path.basename(location.checkoutRoot), identity: location.repositoryIdentity, checkoutRoots: [location.checkoutRoot] };
  }
  /** Backfill only repository identities we can actually discover. Non-Git projects stay unassigned. */
  async initialize() {
    return this.serial(async () => {
      const project = await this.project();
      if (project.repositories !== undefined) return project;
      const repositories: Repository[] = [];
      const roots = new Set([this.checkoutRoot, ...(project.sources ?? []).filter(s => s.corpus.kind === 'git-worktree').map(s => s.corpus.root)]);
      for (const root of roots) {
        const repository = await this.discover(root).catch(() => undefined);
        if (!repository) continue;
        const prior = repositories.find(r => r.id === repository.id);
        if (prior) prior.checkoutRoots = [...new Set([...prior.checkoutRoots, ...repository.checkoutRoots])];
        else repositories.push(repository);
      }
      const next = { ...project, repositories };
      await writeJsonAtomic(this.file, next);
      return next;
    });
  }
  async list() { return (await this.initialize()).repositories ?? []; }
  async register(input: { path: string; name?: string }) {
    const found = await this.discover(input.path, input.name);
    await this.initialize();
    return this.serial(async () => {
      const project = await this.project(), repositories = [...(project.repositories ?? [])];
      const index = repositories.findIndex(repository => repository.id === found.id), prior = repositories[index];
      const repository = { ...found, name: input.name?.trim() || prior?.name || found.name,
        checkoutRoots: [...new Set([...(prior?.checkoutRoots ?? []), ...found.checkoutRoots])] };
      if (index < 0) repositories.push(repository); else repositories[index] = repository;
      await writeJsonAtomic(this.file, { ...project, repositories, updatedAt: new Date().toISOString() });
      return repository;
    });
  }
  private async availableRoot(repository: Repository) {
    let root: string | undefined;
    for (const candidate of repository.checkoutRoots) {
      const location = await discoverRepository(candidate).catch(() => undefined);
      if (location?.repositoryIdentity === repository.identity) { root = candidate; break; }
    }
    if (!root) throw Error('Repository checkout is unavailable');
    return root;
  }
  async captureHunks(context: RepositoryContext) {
    repositoryContextSchema.parse(context);
    const repository = (await this.list()).find(repo => repo.id === context.repositoryId);
    if (!repository) throw Error('Unknown repositoryId');
    return captureGitHunks(await this.availableRoot(repository), context);
  }
  async resolveContext(input: { repositoryId?: string; commits?: string[]; head?: string }) {
    const repositories = await this.list();
    const repository = input.repositoryId ? repositories.find(r => r.id === input.repositoryId) : repositories.length === 1 ? repositories[0] : undefined;
    if (!repository) throw Error('Specify a registered repositoryId for this ChangeSession');
    const root = await this.availableRoot(repository);
    const resolved = new Map<string, string>();
    const resolve = async (ref: string) => {
      if (resolved.has(ref)) return resolved.get(ref)!;
      try {
        const sha = (await execFileAsync('git', ['-C', root!, 'rev-parse', '--verify', '--end-of-options', `${ref}^{commit}`], { encoding: 'utf8' })).stdout.trim();
        resolved.set(ref, sha);
        return sha;
      } catch { throw Error(`Unknown commit in repository ${repository.name}: ${ref}`); }
    };
    const head = await resolve(input.head ?? 'HEAD');
    const commits = new Set<string>();
    for (const ref of input.commits ?? []) commits.add(await resolve(ref));
    return repositoryContextSchema.parse({ repositoryId: repository.id, head, commits: [...commits] });
  }
}

sources.infrastructure/core/persistence/shared.t:
import { execFile } from "node:child_process";
import { createHash, randomUUID } from "node:crypto";
import {
  mkdir,
  readFile,
  realpath,
  rename,
  stat,
  writeFile
} from "node:fs/promises";
import path from "node:path";
import { promisify } from "node:util";
import type { RepositoryLocation } from "../../../application/core/corpus/location";
import type { BuiltInDomainProfileId } from "../../../domain/core/profiles/domainProfile";
import {
  SCHEMA_VERSION,
  type ProjectRecord
} from "../../../domain/core/records/domain";

export const execFileAsync = promisify(execFile);

export async function discoverRepository(inputPath: string): Promise<RepositoryLocation> {
  const resolved = path.resolve(inputPath);
  const info = await stat(resolved).catch(() => null);
  if (!info?.isDirectory()) throw new Error(`repository path is not a directory: ${resolved}`);
  const git = async (...args: string[]) => {
    const result = await execFileAsync("git", ["-C", resolved, ...args], { encoding: "utf8" });
    return result.stdout.trim();
  };
  const checkoutRoot = path.resolve(await git("rev-parse", "--show-toplevel"));
  const commonDirRaw = await git("rev-parse", "--git-common-dir");
  const repositoryIdentity = await realpath(path.resolve(resolved, commonDirRaw));
  const gitRevision = await git("rev-parse", "HEAD").catch(() => undefined);
  return {
    checkoutRoot,
    repositoryIdentity,
    gitRevision,
    domainProfileId: "source-code",
    corpus: { kind: "git-worktree", root: checkoutRoot, ...(gitRevision ? { revision: gitRevision } : {}) }
  };
}

export async function discoverDocumentCorpus(inputPath: string): Promise<RepositoryLocation> {
  const resolved = path.resolve(inputPath);
  const info = await stat(resolved).catch(() => null);
  if (!info?.isDirectory()) throw new Error(`document corpus path is not a directory: ${resolved}`);
  const checkoutRoot = await realpath(resolved);
  return {
    checkoutRoot,
    repositoryIdentity: `filesystem-documents:${checkoutRoot}`,
    domainProfileId: "document",
    corpus: { kind: "filesystem-documents", root: checkoutRoot }
  };
}

export async function discoverDomainCorpus(
  inputPath: string,
  domainProfileId: BuiltInDomainProfileId
): Promise<RepositoryLocation> {
  return domainProfileId === "document"
    ? discoverDocumentCorpus(inputPath)
    : discoverRepository(inputPath);
}

export function projectIdFor(repositoryIdentity: string): string {
  const digest = createHash("sha256").update(repositoryIdentity).digest("hex").slice(0, 12);
  return `project-${digest}`;
}

export function normalizedProject(project: ProjectRecord): ProjectRecord { return project; }

export function nowIso(): string {
  return new Date().toISOString();
}

export function makeId(prefix: string): string {
  return `${prefix}-${randomUUID()}`;
}

export function stableScopedId(prefix: string, ...parts: string[]): string {
  const digest = createHash("sha256").update(parts.join("\0")).digest("hex").slice(0, 32);
  return `${prefix}-${digest}`;
}

export async function readJson<T>(filePath: string): Promise<T> {
  const parsed = JSON.parse(await readFile(filePath, "utf8")) as T & { schemaVersion?: number };
  if (parsed.schemaVersion !== SCHEMA_VERSION) {
    throw new Error(`unsupported schema in ${filePath}`);
  }
  return parsed;
}

export async function readJsonIfExists<T>(filePath: string): Promise<T | null> {
  try {
    return await readJson<T>(filePath);
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
    throw error;
  }
}

export async function writeJsonAtomic(filePath: string, value: unknown): Promise<void> {
  await mkdir(path.dirname(filePath), { recursive: true });
  const tempPath = path.join(
    path.dirname(filePath),
    `.${path.basename(filePath)}.${process.pid}.${randomUUID()}.tmp`
  );
  await writeFile(tempPath, `${JSON.stringify(value, null, 2)}\n`, "utf8");
  await rename(tempPath, filePath);
}

sources.infrastructure/core/persistence/store.ts:
import { GitRepositoryRegistry } from './repositoryRegistry';
import { DiagramPersistence } from '../../../domain/core/diagrams/diagramPersistence';
import { DiagramRevisionStore } from './diagramRevisionStore';
import path from "node:path";
import type { RepositoryLocation } from "../../../application/core/corpus/location";
import {
  type ProjectRecord
} from "../../../domain/core/records/domain";
import type { PersistenceContext } from './context';
import { ProjectCatalogStore } from "./projectCatalogStore";
import * as projectsStore from './projects';
export type { RepositoryLocation } from '../../../application/core/corpus/location';
export { discoverDocumentCorpus, discoverDomainCorpus, discoverRepository, projectIdFor } from './shared';

/** Filesystem repository facade; storage operations are grouped by capability. */
export class DiagramStore {
  readonly repositories: GitRepositoryRegistry;
  readonly checkoutRoot: string;
  readonly storeRoot: string;
  readonly projectCatalogs: ProjectCatalogStore;
  readonly diagramPersistence: DiagramPersistence;
  readonly canvases: ProjectCatalogStore;
  private readonly context: PersistenceContext;
  constructor(checkoutRoot: string, diagramsDirectory = ".diagrams") {
    this.checkoutRoot = path.resolve(checkoutRoot);
    this.storeRoot = path.resolve(this.checkoutRoot, diagramsDirectory);
    this.repositories = new GitRepositoryRegistry(this.storeRoot, this.checkoutRoot);
    this.diagramPersistence = new DiagramPersistence(new DiagramRevisionStore(this.storeRoot));
    this.canvases = new ProjectCatalogStore(this.storeRoot, this.diagramPersistence);
    this.projectCatalogs = this.canvases;
    this.context = { checkoutRoot: this.checkoutRoot, storeRoot: this.storeRoot, projectCatalogs: this.projectCatalogs };
  }
  async ensureProject(location: RepositoryLocation): Promise<ProjectRecord> { await projectsStore.ensureProject(this.context, location); return this.repositories.initialize(); }

  async loadProject(): Promise<ProjectRecord | null> { const project = await projectsStore.loadProject(this.context); return project ? this.repositories.initialize() : null; }
}

